-- Main modifier
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

local mainMod = "Super" -- super / meta / windows key

-- Assign apps
local term = "kitty"
local editor = "neovide"
local file = "dolphin"
local browser = "firefox"

-- Window/Session actions
hl.bind("Super+Shift + P", hl.dsp.exec_cmd("hyprpicker -a"), { description = "Color Picker" })
hl.bind(mainMod .. " + Q", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/dontkillsteam.sh"))
--bind = Alt, F4, exec, /home/ywl/.local/share/bin/dontkillsteam.sh # close focused window
hl.bind(mainMod .. " + Delete", hl.dsp.exit())
hl.bind(mainMod .. " + W", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + G", hl.dsp.group.toggle())
--bind = Alt, Return, fullscreen, # toggle the window between focus and fullscreen
hl.bind(mainMod .. " + L", hl.dsp.exec_cmd("LC_TIME=\"zh_TW.UTF-8\" hyprlock"))
hl.bind("Super+Shift + F", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/windowpin.sh"))
hl.bind(mainMod .. " + Backspace", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/logoutlaunch.sh"))
hl.bind("Ctrl+Alt + W", hl.dsp.exec_cmd("killall waybar || waybar"))

-- Application shortcuts
hl.bind(mainMod .. " + T", hl.dsp.exec_cmd(term))
hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(file))
--bind = Super, C, exec, $editor # launch text editor
--bind = Super, F, exec, $browser # launch web browser
hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ mode = "fullscreen", action = "toggle" }))
hl.bind("Ctrl+Shift + Escape", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/sysmonlaunch.sh"))

-- Rofi menus
hl.bind(mainMod .. " + A", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/rofilaunch.sh d"))
hl.bind(mainMod .. " + Tab", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/rofilaunch.sh w"))
hl.bind("Super+Shift + E", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/rofilaunch.sh f"))

-- Audio control
--bindl  = , F10, exec, /home/ywl/.local/share/bin/volumecontrol.sh -o m # toggle audio mute
--bindel = , F11, exec, /home/ywl/.local/share/bin/volumecontrol.sh -o d # decrease volume
--bindel = , F12, exec, /home/ywl/.local/share/bin/volumecontrol.sh -o i # increase volume
hl.bind("XF86AudioMute", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/volumecontrol.sh -o m"), { locked = true })
hl.bind("XF86AudioMicMute", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/volumecontrol.sh -i m"), { locked = true })
hl.bind("XF86AudioLowerVolume", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/volumecontrol.sh -o d"), { locked = true, repeating = true })
hl.bind("XF86AudioRaiseVolume", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/volumecontrol.sh -o i"), { locked = true, repeating = true })

-- Media control
hl.bind("XF86AudioPlay", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioPause", hl.dsp.exec_cmd("playerctl play-pause"), { locked = true })
hl.bind("XF86AudioNext", hl.dsp.exec_cmd("playerctl next"), { locked = true })
hl.bind("XF86AudioPrev", hl.dsp.exec_cmd("playerctl previous"), { locked = true })

-- Brightness control
hl.bind("XF86MonBrightnessUp", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/brightnesscontrol.sh i"), { locked = true, repeating = true })
hl.bind("XF86MonBrightnessDown", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/brightnesscontrol.sh d"), { locked = true, repeating = true })

-- Move between grouped windows
hl.bind(mainMod .. " + CTRL + H", hl.dsp.group.prev())
hl.bind(mainMod .. " + CTRL + L", hl.dsp.group.next())

-- Screenshot/Screencapture
hl.bind(mainMod .. " + P", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/screenshot.sh s"))
hl.bind("Super+Ctrl + P", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/screenshot.sh sf"))
hl.bind("Super+Alt + P", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/screenshot.sh m"))
--bind = , Print, exec, /home/ywl/.local/share/bin/screenshot.sh p # all monitors screenshot capture

-- Custom scripts
hl.bind("Super+Alt + G", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/gamemode.sh"))
hl.bind("Super+Alt + Right", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/swwwallpaper.sh -n"))
hl.bind("Super+Alt + Left", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/swwwallpaper.sh -p"))
hl.bind("Super+Alt + Up", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/wbarconfgen.sh n"))
hl.bind("Super+Alt + Down", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/wbarconfgen.sh p"))
hl.bind("Super+Shift + R", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/wallbashtoggle.sh -m"))
hl.bind("Super+Shift + T", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/themeselect.sh"))
hl.bind("Super+Shift + A", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/rofiselect.sh"))
hl.bind("Super+Shift + W", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/swwwallselect.sh"))
hl.bind(mainMod .. " + V", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/cliphist.sh c"))
hl.bind("Super+Shift + V", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/cliphist.sh"))
hl.bind(mainMod .. " + K", hl.dsp.exec_cmd("/home/ywl/.local/share/bin/keyboardswitch.sh"))
hl.bind(mainMod .. " + slash", hl.dsp.exec_cmd("pkill -x rofi || /home/ywl/.local/share/bin/keybinds_hint.sh c"))
hl.bind(mainMod .. " + B", hl.dsp.exec_cmd("pkill -x rofi || rofi-rbw --action=copy --clipboarder=wl-copy --selector=rofi --clear-after=15"))

-- Move/Change window focus
hl.bind(mainMod .. " + Left", hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + Right", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + Up", hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + Down", hl.dsp.focus({ direction = "down" }))
--bind = Alt, Tab, movefocus, d

-- Switch workspaces
hl.bind(mainMod .. " + 1", hl.dsp.focus({ workspace = 1 }))
hl.bind(mainMod .. " + 2", hl.dsp.focus({ workspace = 2 }))
hl.bind(mainMod .. " + 3", hl.dsp.focus({ workspace = 3 }))
hl.bind(mainMod .. " + 4", hl.dsp.focus({ workspace = 4 }))
hl.bind(mainMod .. " + 5", hl.dsp.focus({ workspace = 5 }))
hl.bind(mainMod .. " + 6", hl.dsp.focus({ workspace = 6 }))
hl.bind(mainMod .. " + 7", hl.dsp.focus({ workspace = 7 }))
hl.bind(mainMod .. " + 8", hl.dsp.focus({ workspace = 8 }))
hl.bind(mainMod .. " + 9", hl.dsp.focus({ workspace = 9 }))
hl.bind(mainMod .. " + 0", hl.dsp.focus({ workspace = 10 }))

-- Switch workspaces to a relative workspace
--bind = Super+Ctrl, Right, workspace, r+1
--bind = Super+Ctrl, Left, workspace, r-1

-- Move to the first empty workspace
hl.bind("Super+Ctrl + Down", hl.dsp.focus({ workspace = "empty" }))

-- Resize windows
hl.bind("Super+Shift + Right", hl.dsp.window.resize({ x = 30, y = 0, relative = true }), { repeating = true })
hl.bind("Super+Shift + Left", hl.dsp.window.resize({ x = -30, y = 0, relative = true }), { repeating = true })
hl.bind("Super+Shift + Up", hl.dsp.window.resize({ x = 0, y = -30, relative = true }), { repeating = true })
hl.bind("Super+Shift + Down", hl.dsp.window.resize({ x = 0, y = 30, relative = true }), { repeating = true })

-- Move focused window to a workspace
hl.bind("Super+Shift + 1", hl.dsp.window.move({ workspace = 1 }))
hl.bind("Super+Shift + 2", hl.dsp.window.move({ workspace = 2 }))
hl.bind("Super+Shift + 3", hl.dsp.window.move({ workspace = 3 }))
hl.bind("Super+Shift + 4", hl.dsp.window.move({ workspace = 4 }))
hl.bind("Super+Shift + 5", hl.dsp.window.move({ workspace = 5 }))
hl.bind("Super+Shift + 6", hl.dsp.window.move({ workspace = 6 }))
hl.bind("Super+Shift + 7", hl.dsp.window.move({ workspace = 7 }))
hl.bind("Super+Shift + 8", hl.dsp.window.move({ workspace = 8 }))
hl.bind("Super+Shift + 9", hl.dsp.window.move({ workspace = 9 }))
hl.bind("Super+Shift + 0", hl.dsp.window.move({ workspace = 10 }))

-- Move focused window to a relative workspace
hl.bind("Super+Ctrl+Alt + Right", hl.dsp.window.move({ workspace = "r+1" }))
hl.bind("Super+Ctrl+Alt + Left", hl.dsp.window.move({ workspace = "r-1" }))

-- Move active window around current workspace with mainMod + SHIFT + CTRL [←→↑↓]
local moveactivewindow = "grep -q \"true\" <<< $(hyprctl activewindow -j | jq -r .floating) && hyprctl dispatch moveactive"
hl.bind("Super + Shift + Control + left", hl.dsp.exec_cmd(moveactivewindow .. " -30 0 || hyprctl dispatch movewindow l"), { repeating = true, description = "Move activewindow to the right" })
hl.bind("Super + Shift + Control + right", hl.dsp.exec_cmd(moveactivewindow .. " 30 0 || hyprctl dispatch movewindow r"), { repeating = true, description = "Move activewindow to the right" })
hl.bind("Super + Shift + Control + up", hl.dsp.exec_cmd(moveactivewindow .. "  0 -30 || hyprctl dispatch movewindow u"), { repeating = true, description = "Move activewindow to the right" })
hl.bind("Super + Shift + Control + down", hl.dsp.exec_cmd(moveactivewindow .. " 0 30 || hyprctl dispatch movewindow d"), { repeating = true, description = "Move activewindow to the right" })

-- Scroll through existing workspaces
hl.bind(mainMod .. " + mouse_down", hl.dsp.focus({ workspace = "e+1" }))
hl.bind(mainMod .. " + mouse_up", hl.dsp.focus({ workspace = "e-1" }))

-- Move/Resize focused window
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag())
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize())
hl.bind(mainMod .. " + Z", hl.dsp.window.drag())
hl.bind(mainMod .. " + X", hl.dsp.window.resize())

-- Move/Switch to special workspace (scratchpad)
hl.bind("Super+Shift + S", hl.dsp.window.move({ workspace = "special", follow = false }))
hl.bind(mainMod .. " + S", hl.dsp.workspace.toggle_special(""))

-- Toggle focused window split
hl.bind(mainMod .. " + J", hl.dsp.layout("togglesplit"))

-- Move focused window to a workspace silently
hl.bind("Super+Alt + 1", hl.dsp.window.move({ workspace = 1, follow = false }))
hl.bind("Super+Alt + 2", hl.dsp.window.move({ workspace = 2, follow = false }))
hl.bind("Super+Alt + 3", hl.dsp.window.move({ workspace = 3, follow = false }))
hl.bind("Super+Alt + 4", hl.dsp.window.move({ workspace = 4, follow = false }))
hl.bind("Super+Alt + 5", hl.dsp.window.move({ workspace = 5, follow = false }))
hl.bind("Super+Alt + 6", hl.dsp.window.move({ workspace = 6, follow = false }))
hl.bind("Super+Alt + 7", hl.dsp.window.move({ workspace = 7, follow = false }))
hl.bind("Super+Alt + 8", hl.dsp.window.move({ workspace = 8, follow = false }))
hl.bind("Super+Alt + 9", hl.dsp.window.move({ workspace = 9, follow = false }))
hl.bind("Super+Alt + 0", hl.dsp.window.move({ workspace = 10, follow = false }))

-- Toggle fcitx group
hl.bind(mainMod .. " + Space", hl.dsp.exec_cmd("toggle-fcitx-group.sh"))
